<?php

declare(strict_types=1);

$database=require dirname(__DIR__).'/bootstrap/database.php';$pdo=$database->connection();$result=['publications_by_status'=>[],'publications_by_type'=>[],'published_publications'=>0,'authors'=>0,'internal_authors'=>0,'external_authors'=>0,'project_links'=>0,'research_unit_links'=>0];foreach($pdo->query('SELECT status,COUNT(*) total FROM publications WHERE deleted_at IS NULL GROUP BY status')as$r)$result['publications_by_status'][$r['status']]=(int)$r['total'];foreach($pdo->query('SELECT pt.code,COUNT(pub.id) total FROM publication_types pt LEFT JOIN publications pub ON pub.publication_type_id=pt.id AND pub.deleted_at IS NULL GROUP BY pt.id ORDER BY pt.display_order')as$r)$result['publications_by_type'][$r['code']]=(int)$r['total'];$result['published_publications']=(int)$pdo->query('SELECT COUNT(*) FROM publications WHERE status="published" AND published_at IS NOT NULL AND published_at<=NOW() AND deleted_at IS NULL')->fetchColumn();$result['authors']=(int)$pdo->query('SELECT COUNT(*) FROM publication_authors')->fetchColumn();$result['internal_authors']=(int)$pdo->query('SELECT COUNT(*) FROM publication_authors WHERE staff_id IS NOT NULL')->fetchColumn();$result['external_authors']=(int)$pdo->query('SELECT COUNT(*) FROM publication_authors WHERE staff_id IS NULL AND external_author_name IS NOT NULL')->fetchColumn();$result['project_links']=(int)$pdo->query('SELECT COUNT(*) FROM publication_projects')->fetchColumn();$result['research_unit_links']=(int)$pdo->query('SELECT COUNT(*) FROM publication_research_units')->fetchColumn();echo json_encode($result,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR),PHP_EOL;
